# Structured model overview
# Variables: E = elephants produced (integer >= 0)
#            T = tigers produced   (integer >= 0)
# Objective: maximize profit 5*E + 4*T
# Constraint 1: 50*E + 40*T <= 5000   (wood inventory limit)
# Constraint 2: 20*E + 30*T <= 4000   (plastic inventory limit)

DATA = {
    "products": ["elephant", "tiger"],
    "profit": {"elephant": 5, "tiger": 4},
    "wood_usage": {"elephant": 50, "tiger": 40},
    "plastic_usage": {"elephant": 20, "tiger": 30},
    "wood_avail": 5000,
    "plastic_avail": 4000,
}

