    d = DATA if data is None else data

    model = pyo.ConcreteModel()

    model.prod = pyo.Set(initialize=d["products"])

    def _E_bounds(m):
        return (0, None if d["wood_avail"] is None else d["wood_avail"])

    model.E = pyo.Var(domain=pyo.NonNegativeIntegers, bounds=(0, d["wood_avail"]))
    model.T = pyo.Var(domain=pyo.NonNegativeIntegers, bounds=(0, d["wood_avail"]))


    def objective_rule(m):
        return sum(
            (d["profit"][p]) * (
