import pyomo.environ as pyo

DATA = {
    "products": ["elephant", "tiger"],
    "resources": ["wood", "plastic"],
    "profit": {"elephant": 5, "tiger": 4},
    "usage": {
        ("wood", "elephant"): 50,
        ("wood", "tiger"): 40,
        ("plastic", "elephant"): 20,
        ("plastic", "tiger"): 30,
    },
    "availability": {"wood": 5000, "plastic": 4000},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    # Decision: number of each souvenir to produce (indivisible units)
    model.production = pyo.Var(
        model.P, within=pyo.NonNegativeIntegers
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Resource capacity constraints (one per resource)
    def capacity_rule(m, r):
        return sum(
            d["usage"][(r, p)] * m.production[p] for p in m.P
        ) <= d["availability"][r]

    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "products": ["elephant", "tiger"],
    "resources": ["wood", "plastic"],
    "profit": {"elephant": 5, "tiger": 4},
    "usage": {
        "wood": {"elephant": 50, "tiger": 40},
        "plastic": {"elephant": 20, "tiger": 30},
    },
    "availability": {"wood": 5000, "plastic": 4000},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.PRODUCTS = pyo.Set(initialize=d["products"])
    model.RESOURCES = pyo.Set(initialize=d["resources"])

    # x[p] = number of souvenirs of product p produced (integer, >= 0)
    model.x = pyo.Var(
        model.PRODUCTS, within=pyo.NonNegativeIntegers, bounds=(0, None)
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Resource availability constraints (one per resource)
    def resource_rule(m, r):
        return (
            sum(d["usage"][r][p] * m.x[p] for p in m.PRODUCTS)
            <= d["availability"][r]
        )

    model.resource_limit = pyo.Constraint(
        model.RESOURCES, rule=resource_rule
    )

    return model


